const source = $json.body ?? $json;

const cleanString = (value) => {
  if (value === null || value === undefined) return '';
  return String(value).trim();
};

const email = cleanString(source.email).toLowerCase();

const companySizeNumber = Number(source.companySize);
const budgetNumber = Number(source.budget);

const lead = {
  name: cleanString(source.name),
  email,
  company: cleanString(source.company),
  jobTitle: cleanString(source.jobTitle),

  companySize:
    Number.isFinite(companySizeNumber) && companySizeNumber >= 0
      ? companySizeNumber
      : null,

  budget:
    Number.isFinite(budgetNumber) && budgetNumber >= 0
      ? budgetNumber
      : null,

  timeline: cleanString(source.timeline),
  message: cleanString(source.message),

  receivedAt: new Date().toISOString()
};

const errors = [];

const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

if (!lead.name) {
  errors.push('name is required');
}

if (!lead.email) {
  errors.push('email is required');
} else if (!emailPattern.test(lead.email)) {
  errors.push('email is invalid');
}

if (!lead.message) {
  errors.push('message is required');
}

if (lead.message.length > 5000) {
  errors.push('message exceeds 5000 characters');
}

if (
  source.companySize !== undefined &&
  lead.companySize === null
) {
  errors.push('companySize must be a non-negative number');
}

if (
  source.budget !== undefined &&
  lead.budget === null
) {
  errors.push('budget must be a non-negative number');
}

return {
  json: {
    ...lead,
    isValid: errors.length === 0,
    validationErrors: errors
  }
};

return {
  json: {
    accepted: false,
    status: "rejected",
    reason: "Lead validation failed",
    validationErrors: $json.validationErrors,
    receivedAt: $json.receivedAt
  }
};

const lead = { ...$json };

let score = 0;
const scoreReasons = [];

const addScore = (points, reason) => {
  score += points;
  scoreReasons.push({
    points,
    reason
  });
};

// -------------------------
// 1. Budget signal
// -------------------------
const budget = Number.isFinite(lead.budget)
  ? lead.budget
  : 0;

if (budget >= 2000) {
  addScore(30, 'Budget is $2,000 or more');
} else if (budget >= 1000) {
  addScore(25, 'Budget is between $1,000 and $1,999');
} else if (budget >= 500) {
  addScore(15, 'Budget is between $500 and $999');
} else if (budget > 0) {
  addScore(5, 'Budget provided but below $500');
}

// -------------------------
// 2. Company-size signal
// -------------------------
const companySize = Number.isFinite(lead.companySize)
  ? lead.companySize
  : 0;

if (companySize >= 50) {
  addScore(20, 'Company has 50 or more employees');
} else if (companySize >= 20) {
  addScore(15, 'Company has between 20 and 49 employees');
} else if (companySize >= 5) {
  addScore(10, 'Company has between 5 and 19 employees');
} else if (companySize > 0) {
  addScore(5, 'Company size is known');
}

// -------------------------
// 3. Timeline / urgency
// -------------------------
const timeline = String(lead.timeline || '')
  .trim()
  .toLowerCase();

if (
  /\b(asap|urgent|immediately|today|this week|1 week|within a week)\b/i.test(
    timeline
  )
) {
  addScore(20, 'Very urgent implementation timeline');
} else if (
  /\b(2 weeks|two weeks|this month|30 days|within a month)\b/i.test(
    timeline
  )
) {
  addScore(15, 'Near-term implementation timeline');
} else if (
  /\b(1 month|2 months|3 months|quarter)\b/i.test(
    timeline
  )
) {
  addScore(8, 'Medium-term implementation timeline');
}

// -------------------------
// 4. Decision-maker signal
// -------------------------
const jobTitle = String(lead.jobTitle || '')
  .trim()
  .toLowerCase();

/*
  Word boundaries are important here.

  Without \b, "coo" would incorrectly match:
  "coordinator"

  With \b, COO only matches the actual title/word COO.
*/
const decisionMakerPattern =
  /\b(owner|founder|chief|ceo|cto|coo|cfo|cio|director|head|manager|vp|vice president)\b/i;

if (decisionMakerPattern.test(jobTitle)) {
  addScore(
    15,
    'Contact appears to be a decision-maker or manager'
  );
}

// -------------------------
// 5. Automation intent
// -------------------------
const message = String(lead.message || '')
  .trim()
  .toLowerCase();

/*
  Use patterns rather than simple message.includes()
  so short keywords such as "ai" don't match inside
  unrelated words such as "email".
*/
const intentPatterns = [
  {
    label: 'automate',
    pattern: /\bautomate\b/i
  },
  {
    label: 'automation',
    pattern: /\bautomation\b/i
  },
  {
    label: 'workflow',
    pattern: /\bworkflow(s)?\b/i
  },
  {
    label: 'integration',
    pattern: /\bintegration(s)?\b/i
  },
  {
    label: 'crm',
    pattern: /\bcrm\b/i
  },
  {
    label: 'lead',
    pattern: /\blead(s)?\b/i
  },
  {
    label: 'follow-up',
    pattern: /\bfollow[\s-]?up(s)?\b/i
  },
  {
    label: 'sales',
    pattern: /\bsales\b/i
  },
  {
    label: 'api',
    pattern: /\bapi(s)?\b/i
  },
  {
    label: 'n8n',
    pattern: /\bn8n\b/i
  },
  {
    label: 'ai',
    pattern: /\bai\b/i
  },
  {
    label: 'customer support',
    pattern: /\bcustomer support\b/i
  }
];

const matchedTerms = intentPatterns
  .filter(({ pattern }) => pattern.test(message))
  .map(({ label }) => label);

if (matchedTerms.length > 0) {
  const intentPoints = Math.min(
    15,
    matchedTerms.length * 3
  );

  addScore(
    intentPoints,
    `Strong automation intent: ${matchedTerms.join(', ')}`
  );
}

// -------------------------
// 6. Lead completeness
// -------------------------
if (lead.company && lead.jobTitle) {
  addScore(
    5,
    'Company and job title were provided'
  );
}

// -------------------------
// Clamp score to 0–100
// -------------------------
score = Math.max(
  0,
  Math.min(100, score)
);

// -------------------------
// Lead temperature
// -------------------------
let leadTemperature = 'COLD';

if (score >= 70) {
  leadTemperature = 'HOT';
} else if (score >= 40) {
  leadTemperature = 'WARM';
}

// -------------------------
// Final result
// -------------------------
return {
  json: {
    ...lead,

    accepted: true,

    leadScore: score,
    leadTemperature,

    scoringVersion: '1.1',

    scoreReasons,

    scoredAt: new Date().toISOString()
  }
};

