const lead = {
  ...$('Score Lead Deterministically').first().json
};

const raw = $json ?? {};

// --------------------------------------------------
// Determine which provider actually produced output
// --------------------------------------------------

const ollamaExecuted =
  $('AI Enrich Lead - Ollama Fallback').isExecuted;

const aiProvider =
  ollamaExecuted ? 'ollama' : 'openai';

const aiModel =
  aiProvider === 'ollama'
    ? 'qwen2.5:3b-instruct'
    : 'gpt-6.1-terra';

const aiFallbackUsed =
  aiProvider === 'ollama';


// --------------------------------------------------
// Detect provider/node failure
// --------------------------------------------------

const errorMessage =
  raw?.error?.message ??
  raw?.error ??
  raw?.errorMessage ??
  (
    typeof raw?.message === 'string'
      ? raw.message
      : raw?.message?.error
  ) ??
  '';


// --------------------------------------------------
// Safe failure result
// --------------------------------------------------

const failedResult = {
  ...lead,

  aiLeadSummary: '',
  aiBusinessNeed: '',
  aiPainPoints: '',
  aiAutomationOpportunities: '',
  aiPurchaseIntent: 'unknown',
  aiUrgencyAssessment: '',
  aiRecommendedSolution: '',
  aiSalesTalkingPoints: '',
  aiRecommendedNextAction: '',
  aiConfidence: 0,

  aiProvider,
  aiModel,
  aiFallbackUsed,

  aiEnrichmentStatus: 'failed',
  aiEnrichmentError:
    String(errorMessage || 'AI enrichment unavailable')
      .slice(0, 500),

  aiEnrichmentVersion: '1.0',
  aiPromptVersion: '1.0',

  aiEnrichedAt: new Date().toISOString()
};

if (errorMessage) {
  return {
    json: failedResult
  };
}


// --------------------------------------------------
// Locate structured AI output
// --------------------------------------------------

let ai =
  raw.output ??
  raw.result ??
  raw.data ??
  raw;


// --------------------------------------------------
// Parse JSON text when a model returns a string
// --------------------------------------------------

if (typeof ai === 'string') {
  try {
    ai = JSON.parse(ai);
  } catch {
    return {
      json: {
        ...failedResult,
        aiEnrichmentError:
          'AI returned output that could not be parsed as JSON'
      }
    };
  }
}


// --------------------------------------------------
// Helpers
// --------------------------------------------------

const toArray = (value) =>
  Array.isArray(value) ? value : [];

const confidenceValue =
  Number(ai.aiConfidence);

const confidence =
  Number.isFinite(confidenceValue)
    ? Math.max(0, Math.min(0.95, confidenceValue))
    : 0;


// --------------------------------------------------
// Successful enrichment
// --------------------------------------------------

return {
  json: {
    ...lead,

    aiLeadSummary:
      String(ai.leadSummary ?? ''),

    aiBusinessNeed:
      String(ai.businessNeed ?? ''),

    aiPainPoints:
      toArray(ai.painPoints).join(' | '),

    aiAutomationOpportunities:
      toArray(ai.automationOpportunities).join(' | '),

    aiPurchaseIntent:
      String(ai.purchaseIntent ?? 'unknown'),

    aiUrgencyAssessment:
      String(ai.urgencyAssessment ?? ''),

    aiRecommendedSolution:
      String(ai.recommendedSolution ?? ''),

    aiSalesTalkingPoints:
      toArray(ai.salesTalkingPoints).join(' | '),

    aiRecommendedNextAction:
      String(ai.recommendedNextAction ?? ''),

    aiConfidence:
      confidence,

    aiProvider,
    aiModel,
    aiFallbackUsed,

    aiEnrichmentStatus: 'success',
    aiEnrichmentError: '',

    aiEnrichmentVersion: '1.0',
    aiPromptVersion: '1.0',

    aiEnrichedAt:
      new Date().toISOString()
  }
};

