const lead = { ...$json };

// ---------------------------------------
// Lifecycle configuration
// ---------------------------------------

const lifecycleRules = {
  HOT: {
    priority: 'P1',
    slaHours: 1
  },

  WARM: {
    priority: 'P2',
    slaHours: 24
  },

  COLD: {
    priority: 'P3',
    slaHours: 72
  }
};

const temperature =
  String(lead.leadTemperature || 'COLD')
    .toUpperCase();

const rule =
  lifecycleRules[temperature] ??
  lifecycleRules.COLD;


// ---------------------------------------
// SLA starts when the lead was received
// ---------------------------------------

const received =
  new Date(lead.receivedAt);

const baseTime =
  Number.isNaN(received.getTime())
    ? new Date()
    : received;

const slaDue =
  new Date(
    baseTime.getTime() +
    rule.slaHours * 60 * 60 * 1000
  );


// ---------------------------------------
// Human-readable unique Lead ID
// ---------------------------------------

const datePart =
  baseTime
    .toISOString()
    .slice(0, 10)
    .replace(/-/g, '');

const executionId =
  String($execution.id || '')
    .replace(/[^a-zA-Z0-9]/g, '');

const fallbackId =
  Math.random()
    .toString(36)
    .slice(2, 8)
    .toUpperCase();

const leadId =
  `CL-${datePart}-${executionId || fallbackId}`;


// ---------------------------------------
// Lifecycle record
// ---------------------------------------

return {
  json: {
    ...lead,

    leadId,

    lifecycleStatus: 'NEW',

    priority:
      rule.priority,

    assignedOwner:
      'CedarLead Sales Queue',

    assignedOwnerEmail:
      '',

    slaHours:
      rule.slaHours,

    slaDueAt:
      slaDue.toISOString(),

    nextFollowUpAt:
      slaDue.toISOString(),

    lastContactedAt:
      '',

    statusUpdatedAt:
      new Date().toISOString(),

    lastEscalatedAt:
      '',

    escalationCount:
      0,

    lifecycleVersion:
      '1.0'
  }
};
